1	// Command mevwatch is the MEV 与链上风险监控系统 entry point.
2	package main
3	
4	import (
5		"encoding/json"
6		"fmt"
7		"io"
8		"os"
9		"strconv"
10		"strings"
11	
12		"github.com/gzhysuiioo/mevwatch-guard/mevwatch"
13	)
14	
15	func main() {
16		command := "demo"
17		if len(os.Args) > 1 {
18			command = os.Args[1]
19		}
20		switch command {
21		case "demo":
22			runDemo()
23		case "version":
24			fmt.Println("mevwatch 0.1.0")
25		case "replay":
26			runReplay(os.Args[2:])
27		case "report":
28			if len(os.Args) != 5 {
29				fmt.Fprintln(os.Stderr, "usage: mevwatch report <archive-dir> <chainId> <blockHash>")
30				os.Exit(2)
31			}
32			report, err := mevwatch.Query(os.Args[2], os.Args[3], os.Args[4])
33			if err != nil {
34				fmt.Fprintf(os.Stderr, "report: %v\n", err)
35				os.Exit(1)
36			}
37			writeJSON(report)
38		case "rules":
39			runRules(os.Args[2:])
40		case "alerts":
41			runAlerts(os.Args[2:])
42		case "suppressions":
43			runSuppressions(os.Args[2:])
44		case "reviews":
45			runReviews(os.Args[2:])
46		case "compare":
47			if len(os.Args) != 6 {
48				fmt.Fprintln(os.Stderr, "usage: mevwatch compare <archive-dir> <chainId> <blockHash> <version-id>")
49				os.Exit(2)
50			}
51			result, err := mevwatch.Compare(os.Args[2], os.Args[3], os.Args[4], os.Args[5])
52			if err != nil {
53				fmt.Fprintf(os.Stderr, "compare: %v\n", err)
54				os.Exit(1)
55			}
56			writeJSON(result)
57		case "help", "-h", "--help":
58			usage()
59		default:
60			fmt.Fprintf(os.Stderr, "unknown command %q\n", command)
61			usage()
62			os.Exit(2)
63		}
64	}
65	
66	func usage() {
67		fmt.Println("usage: mevwatch [command]")
68		fmt.Println("  demo                                     run the built-in sandwich demo (default)")
69		fmt.Println("  version                                  print version")
70		fmt.Println("  replay [--version <id>] <input> <dir>    import line-delimited blocks into the archive")
71		fmt.Println("  report <archive-dir> <chainId> <hash>    print the archived block report")
72		fmt.Println("  rules list <archive-dir>                 list rule versions and the enabled one")
73		fmt.Println("  rules show <archive-dir> <version-id>    print one version's full parameters")
74		fmt.Println("  rules register <archive-dir> <spec-file> register a rule version ('-' reads stdin)")
75		fmt.Println("  rules enable <archive-dir> <version-id>  enable a registered version for later replays")
76		fmt.Println("  compare <archive-dir> <chainId> <hash> <version-id>")
77		fmt.Println("                                           re-judge an archived block under a version and diff")
78		fmt.Println("  alerts generate <archive-dir> <chainId> <startHeight> <endHeight> <minSeverity> <channel>")
79		fmt.Println("                                           generate offline alerts from archived conclusions")
80		fmt.Println("  alerts history <archive-dir> <chainId> <channel> <startHeight> <endHeight>")
81		fmt.Println("                                           query stored alert/suppression records")
82		fmt.Println("  suppressions list <archive-dir>          list registered suppression conditions")
83		fmt.Println("  suppressions register <archive-dir> <spec-file>")
84		fmt.Println("                                           register a suppression condition ('-' reads stdin)")
85		fmt.Println("  suppressions revoke <archive-dir> <id>   revoke a registered suppression condition")
86		fmt.Println("  reviews submit <archive-dir> <spec-file> submit a manual review ('-' reads stdin)")
87		fmt.Println("  reviews history <archive-dir> <chainId> <blockHash> <txHash> <kind>")
88		fmt.Println("                                           query a conclusion's current review and revisions")
89		fmt.Println("  reviews evaluate <archive-dir> <chainId> <startHeight> <endHeight> <version-id>")
90		fmt.Println("                                           false-positive analysis over a height range")
91	}
92	
93	func runReplay(args []string) {
94		versionID := ""
95		rest := args
96		if len(rest) >= 1 && strings.HasPrefix(rest[0], "--version=") {
97			versionID = strings.TrimPrefix(rest[0], "--version=")
98			rest = rest[1:]
99		} else if len(rest) >= 2 && rest[0] == "--version" {
100			versionID = rest[1]
101			rest = rest[2:]
102		}
103		if len(rest) != 2 {
104			fmt.Fprintln(os.Stderr, "usage: mevwatch replay [--version <id>] <input-file> <archive-dir>")
105			os.Exit(2)
106		}
107		var reports []mevwatch.Report
108		var err error
109		if versionID != "" {
110			reports, err = mevwatch.ReplayFileWithVersion(rest[0], rest[1], versionID)
111		} else {
112			reports, err = mevwatch.ReplayFile(rest[0], rest[1])
113		}
114		if err != nil {
115			fmt.Fprintf(os.Stderr, "replay: %v\n", err)
116			os.Exit(1)
117		}
118		for _, report := range reports {
119			writeJSON(report)
120		}
121	}
122	
123	func runRules(args []string) {
124		if len(args) < 1 {
125			fmt.Fprintln(os.Stderr, "usage: mevwatch rules <list|show|register|enable> ...")
126			os.Exit(2)
127		}
128		switch args[0] {
129		case "list":
130			if len(args) != 2 {
131				fmt.Fprintln(os.Stderr, "usage: mevwatch rules list <archive-dir>")
132				os.Exit(2)
133			}
134			versions, enabled, err := mevwatch.ListVersions(args[1])
135			if err != nil {
136				fmt.Fprintf(os.Stderr, "rules list: %v\n", err)
137				os.Exit(1)
138			}
139			writeJSON(struct {
140				Enabled  string                 `json:"enabled"`
141				Versions []mevwatch.RuleVersion `json:"versions"`
142			}{Enabled: enabled, Versions: versions})
143		case "show":
144			if len(args) != 3 {
145				fmt.Fprintln(os.Stderr, "usage: mevwatch rules show <archive-dir> <version-id>")
146				os.Exit(2)
147			}
148			version, err := mevwatch.GetVersion(args[1], args[2])
149			if err != nil {
150				fmt.Fprintf(os.Stderr, "rules show: %v\n", err)
151				os.Exit(1)
152			}
153			writeJSON(version)
154		case "register":
155			if len(args) != 3 {
156				fmt.Fprintln(os.Stderr, "usage: mevwatch rules register <archive-dir> <spec-file>")
157				os.Exit(2)
158			}
159			var raw []byte
160			var err error
161			if args[2] == "-" {
162				raw, err = io.ReadAll(os.Stdin)
163			} else {
164				raw, err = os.ReadFile(args[2])
165			}
166			if err != nil {
167				fmt.Fprintf(os.Stderr, "rules register: %v\n", err)
168				os.Exit(1)
169			}
170			version, created, err := mevwatch.RegisterVersion(args[1], raw)
171			if err != nil {
172				fmt.Fprintf(os.Stderr, "rules register: %v\n", err)
173				os.Exit(1)
174			}
175			writeJSON(struct {
176				Created bool                 `json:"created"`
177				Version mevwatch.RuleVersion `json:"version"`
178			}{Created: created, Version: version})
179		case "enable":
180			if len(args) != 3 {
181				fmt.Fprintln(os.Stderr, "usage: mevwatch rules enable <archive-dir> <version-id>")
182				os.Exit(2)
183			}
