307		if _, _, err := RegisterVersion(dir, []byte(off)); err != nil {
308			t.Fatal(err)
309		}
310		if _, err := ReplayWithVersion(strings.NewReader(incomplete), dir, "off"); err == nil {
311			t.Fatal("replay under rules-off version must still reject an incomplete record")
312		}
313		// Same for a file-based replay entry point.
314		path := filepath.Join(t.TempDir(), "blocks.jsonl")
315		if err := os.WriteFile(path, []byte(incomplete), 0o644); err != nil {
316			t.Fatal(err)
317		}
318		if _, err := ReplayFileWithVersion(path, t.TempDir(), "builtin"); err == nil {
319			t.Fatal("ReplayFileWithVersion must reject an incomplete record")
320		}
321	}
