603		res = runCLI(t, "reviews", "evaluate", dir, "1", "0", "100", "builtin")
604		if res.exitCode != 0 {
605			t.Fatalf("evaluate under builtin failed: %d %q", res.exitCode, res.stderr)
606		}
607		var eval struct {
608			StillHit int `json:"stillHit"`
609			Pending  int `json:"pending"`
610			Version  struct {
611				ID string `json:"id"`
612			} `json:"version"`
613		}
614		if err := json.Unmarshal([]byte(res.stdout), &eval); err != nil {
615			t.Fatalf("stdout is not valid JSON: %v\n%s", err, res.stdout)
616		}
617		if eval.Version.ID != "builtin" || eval.StillHit != 1 || eval.Pending != 1 {
618			t.Fatalf("builtin evaluation stats wrong: %s", res.stdout)
619		}
620	}
621	
622	// TestCLIReviewEvaluateCorruptVersionEmptyRange proves the corrupt
623	// candidate is refused even when the range matches no blocks: the failure
624	// is about the archived rule version, not about the range contents.
625	func TestCLIReviewEvaluateCorruptVersionEmptyRange(t *testing.T) {
626		dir := setupReviewCLIArchive(t)
627		corruptStoredVersion(t, dir, "mult3", func(ver map[string]any) {
628			ver["rules"].(map[string]any)["displacement"].(map[string]any)["multiplier"] = 0
629		})
630		res := runCLI(t, "reviews", "evaluate", dir, "1", "1000", "2000", "mult3")
631		if res.exitCode != 1 || res.stdout != "" || !strings.Contains(res.stderr, "corrupt") ||
632			!strings.Contains(res.stderr, "mult3") {
633			t.Fatalf("empty-range failure shape wrong: exit=%d stdout=%q stderr=%q",
634				res.exitCode, res.stdout, res.stderr)
635		}
636	}
