func (r record) id() blockID { return blockID{r.ChainID, r.BlockHash} }

func (r record) ruleVersion() RuleVersion {
	if r.Version != nil {
		return *r.Version
	}
	return BuiltinVersion()
}

// queryRecord mirrors one archived record the way a report query reads it.
// Every business field is decoded normally, but the archived rule-version
// declaration is kept as its raw stored document with its presence bit —
// the same shape a registered version is kept in while the archive is read
// and written. The decoded struct cannot tell a missing field, an explicit
